/**
 * Embed the Neovim plugin (editors/nvim) in the CLI, so `hedgesync editor
 * nvim install` always installs the copy that matches the binary.
 *
 * Writes src/cli/nvim-plugin.generated.ts. Run with `bun run gen:nvim`; a
 * unit test fails when the generated file is stale.
 */
import { readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { join, relative, sep } from 'node:path';

const ROOT = join(import.meta.dir, '..');
const PLUGIN = join(ROOT, 'editors/nvim');
export const GENERATED = join(ROOT, 'src/cli/nvim-plugin.generated.ts');

function walk(dir: string): string[] {
  return readdirSync(dir).sort().flatMap((name) => {
    const path = join(dir, name);
    return statSync(path).isDirectory() ? walk(path) : [path];
  });
}

export function renderPluginModule(): string {
  const files = walk(PLUGIN)
    .map(path => relative(PLUGIN, path).split(sep).join('/'))
    .filter(path => path === 'README.md' || path.startsWith('lua/') || path.startsWith('plugin/'));
  const entries = files.map(path => `  ${JSON.stringify(path)}: ${JSON.stringify(readFileSync(join(PLUGIN, path), 'utf8'))},`);
  return `// Generated by scripts/gen-nvim-plugin.ts from editors/nvim. Do not edit.
// Regenerate with: bun run gen:nvim

/** The Neovim plugin's files, by path relative to the plugin root. */
export const NVIM_PLUGIN_FILES: Record<string, string> = {
${entries.join('\n')}
};
`;
}

if (import.meta.main) {
  writeFileSync(GENERATED, renderPluginModule());
  console.log(`wrote ${relative(ROOT, GENERATED)}`);
}
